 * Uses AnyEventEnvelopeSchema.parse() for runtime validation,
 * respecting exactOptionalPropertyTypes (no Partial<AnyEventEnvelope>).
 */
export function makeEnvelope(overrides: Record<string, unknown>): AnyEventEnvelope {
